// Hand-written `next` stub for the flowatlas fixture suite: the `pages/api`
// handler's request and response, which are Express's shape again.

export interface IncomingHttpHeaders {
  host?: string;
  [header: string]: string | string[] | undefined;
}

export interface NextApiRequest {
  body: any;
  query: Partial<{ [key: string]: string | string[] }>;
  headers: IncomingHttpHeaders;
  method?: string;
}

export interface NextApiResponse<Data = any> {
  status(code: number): NextApiResponse<Data>;
  json(body: Data): void;
  send(body: Data): void;
}
